
import Checkins from "./Data/Checkins";
import ChangePass from "./Data/ChangePassword";
import ChangeData from "./Data/ChangeData";
import AddAttendee from "./Data/AddAttendee";
import Bluetooth from "./Data/Bluetooth";
import SignIn from "./Data/SignIn";
import EventLists from "./Data/EventLists";
import AddEvents from "./Data/AddEvents";
import { createStackNavigator } from "@react-navigation/stack";
import React, {useState} from "react";
import {
  NavigationContainer,
} from "@react-navigation/native";
import AppLoading from "expo-app-loading";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Platform, Text, LogBox} from "react-native";
import * as Font from "expo-font";
import { FontAwesome, Ionicons, MaterialCommunityIcons, Feather } from '@expo/vector-icons';
import { Asset } from 'expo-asset';
import WebViewer from "./Data/WebView";
import { AlertNotificationRoot} from 'react-native-alert-notification';


export default function App() {
  const Stack = createStackNavigator();
  const [signIn, setSignIn] = useState(false);
  const [isReady, setIsReady] = useState(false);
  LogBox.ignoreAllLogs(true)

  Text.defaultProps = Text.defaultProps || {};
  Text.defaultProps.allowFontScaling = false;

  function cacheImages(images) {
    return images.map(image => {
        if (typeof image === 'string') {
            return Image.prefetch(image);
        } else {
            return Asset.fromModule(image).downloadAsync();
        }
    });
}

function cacheFonts(fonts) {
    return fonts.map(async font => await Font.loadAsync(font));
  }


if (Platform.OS === 'ios' || Platform.OS === 'android') {
  LogBox.ignoreLogs(['Setting a timer']);
}

  async function loadAssetsAsync() {
    await Font.loadAsync(
      'FontAwesome',
      require('./Data/fonts/FontAwesome.ttf')
    );

    try {
      const imageAssets = cacheImages([
        require('./assets/icon.png'),
    ]);

    const fontAssets = cacheFonts([FontAwesome.font, Ionicons.font, MaterialCommunityIcons.font, Feather.font]);

    await Promise.all([...imageAssets, ...fontAssets, FontAwesome.font ]);

    const value =
      Platform.OS !== "web"
        ? await AsyncStorage.getItem("logedIn")
        : window.localStorage.getItem("logedIn");
    if (value !== null) {
      setSignIn(true);
    } else {
      setSignIn(false);
    }
  } catch (error) {
    setSignIn(false);
  }
}

if (!isReady) {
  return (
    <AppLoading
      startAsync={loadAssetsAsync}
      onFinish={() => {
        setTimeout(() => {
          setIsReady(true);
        }, 1500);
      }}
      onError={console.warn}
    />
  );
}

  if (signIn) {
    return (
      <NavigationContainer>
        <AlertNotificationRoot>
              <Stack.Navigator initialRouteName="EventLists">
              <Stack.Screen
                  name="Event List"
                  component={EventLists}
                  options={{
                    gestureEnabled: false,
                    headerShown: true,
                    headerLeft: () => <></>,
                  }}   
                />
            <Stack.Screen
                    name="Add New Event"
                    component={AddEvents}
                    options={{ headerShown: true, headerBackTitleVisible: false,headerTintColor: '#000000' }}
                  />
                <Stack.Screen
                  name="Check In Attendees"
                  options={({ route }) => ({ title: route.params.kiosk_event + " Attendee Check In",  headerShown: true, headerBackTitleVisible: false,headerTintColor: '#000000'}) } // what 
                  component={Checkins}
                />
            <Stack.Screen
                    name="Kiosk Settings"
                    component={Bluetooth}
                    options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                  />
           <Stack.Screen
                    name="Add Attendee"
                    component={AddAttendee}
                    options={{ headerShown: true, headerBackTitleVisible: false,headerTintColor: '#000000' }}
                  />
                  <Stack.Screen
                  name="WebView"
                  component={WebViewer}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
                                                  <Stack.Screen
                  name="Change Password"
                  component={ChangePass}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
              <Stack.Screen
                  name="Change Account Details"
                  component={ChangeData}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
              </Stack.Navigator>
              </AlertNotificationRoot>
      </NavigationContainer>
    );
    }else{
      return (
      <NavigationContainer>
        <AlertNotificationRoot>
                <Stack.Navigator initialRouteName="SignIn">
                  <Stack.Screen
                    name="Kiosk Sign In"
                    component={SignIn}
                    options={{ headerShown: false }}

                  />
                <Stack.Screen
                  name="Event List"
                  options={{
                    gestureEnabled: false,
                    headerShown: true,
                    headerLeft: () => <></>,
                  }}
                  component={EventLists}
                />
                <Stack.Screen
                    name="Add New Event"
                    component={AddEvents}
                    options={{ headerShown: true, headerBackTitleVisible: false,headerTintColor: '#000000' }}
                  />
                <Stack.Screen
                  name="Check In Attendees"
                  options={{ headerShown: true, headerBackTitleVisible: false,headerTintColor: '#000000' }}
                  component={Checkins}
                />
                            <Stack.Screen
                    name="Kiosk Settings"
                    component={Bluetooth}
                    options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                  />
               <Stack.Screen
                    name="Add Attendee"
                    component={AddAttendee}
                    options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                  />
                  <Stack.Screen
                  name="WebView"
                  component={WebViewer}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
                                  <Stack.Screen
                  name="Change Password"
                  component={ChangePass}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
                <Stack.Screen
                  name="Change Account Details"
                  component={ChangeData}
                  options={{ headerShown: true, headerBackTitleVisible: false, headerTintColor: '#000000' }}
                />
                </Stack.Navigator>
                </AlertNotificationRoot>
        </NavigationContainer>
      );
    }
}
